import { defineStore } from 'pinia'

export const useProgressTracker = defineStore('progress', {
  state: () => ({
    done: [] as string[]
  }),
  getters: {
    percentOf(state) {
      return (total: number): number =>
        total === 0 ? 0 : Math.round((state.done.length * 100) / total)
    },
    isDone(state) {
      return (id: string): boolean => state.done.includes(id)
    }
  },
  actions: {
    mark(id: string) {
      if (!this.done.includes(id)) this.done.push(id)
    },
    unmark(id: string) {
      this.done = this.done.filter((d) => d !== id)
    }
  }
})
